{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError("missing fields")
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be non-empty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be list")
    node_map = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("node must be dict")
        nid = node.get('id')
        if nid is None:
            raise ValueError("node missing id")
        if nid in node_map:
            raise ValueError("duplicate id")
        node_map[nid] = {k: v for k, v in node.items()}
    root = None
    for nid, node in node_map.items():
        if node.get('parent') is None:
            if root is not None:
                raise ValueError("multiple roots")
            root = nid
            if node.get('depth') != 0:
                raise ValueError("root depth must be 0")
            if node.get('symbol') != 'root':
                raise ValueError("root symbol must be 'root'")
            if node.get('removable') != False:
                raise ValueError("root must not be removable")
    if root is None:
        raise ValueError("no root node")
    if 'root' not in required_symbols:
        raise ValueError("required_symbols must include 'root'")
    children = {nid: [] for nid in node_map}
    for nid, node in node_map.items():
        parent = node.get('parent')
        if parent is not None:
            if parent not in children:
                raise ValueError("parent not found")
            children[parent].append(nid)
    node_order = sorted(node_map.keys(), key=lambda nid: (-node_map[nid]['depth'], nid))
    removed = set()
    removal_order = []
    def check_required_symbols(removed_set):
        for sym in required_symbols:
            found = False
            for nid, node in node_map.items():
                if nid not in removed_set and node['symbol'] == sym:
                    found = True
                    break
            if not found:
                return False
        return True
    for nid in node_order:
        node = node_map[nid]
        if not node['removable']:
            continue
        if node.get('parent') is None:
            continue
        has_retained_child = any(cid not in removed for cid in children[nid])
        if has_retained_child:
            continue
        removed.add(nid)
        if not check_required_symbols(removed):
            removed.remove(nid)
        else:
            removal_order.append(nid)
    retained = [nid for nid in node_map if nid not in removed]
    retained_sorted = sorted(retained)
    return {'retained': retained_sorted, 'removal_order': removal_order}"}
